    // A click that names its pointer is judged by that pointer. A
    // compatibility mouse event, or a click sent as a plain mouse event,
    // belongs to the last press.
    const {pointerType} = event as Partial<PointerEvent>;
    const isHeldPress =
      lastPress === 'held' &&
      (pointerType == null ||
        pointerType === '' ||
